// Authored A2 curriculum, Unit 5: future plans, arrangements, suggestions and obligations.
Map<String, dynamic> _u5(int n, String title, String explanation, String example, String french, String question, List<String> options, int answer, String correction) => <String,dynamic>{'id':'A2-U05-L${n.toString().padLeft(2,'0')}','level':'A2','title':title,'subtitle':'Projets et interactions • Leçon $n/50','explanation':explanation,'example':example,'french':french,'question':question,'options':options,'answer':answer,'correction':correction,'unit':5,'phase':0};
final List<Map<String,dynamic>> a2Unit5CourseData = <Map<String,dynamic>>[
 _u5(1,"Present continuous for arrangements","Use the present continuous for a definite future arrangement, often with a time.","I’m meeting my cousin at six tomorrow.","Je rencontre mon cousin demain à six heures.","Which sentence is a future arrangement?",["I’m meeting Ana tomorrow.","I meet Ana yesterday.","I meeting Ana tomorrow."],0,"I’m meeting describes a planned arrangement."),
 _u5(2,"Present continuous questions about plans","Put am/is/are before the subject to ask about a future arrangement.","Are you travelling this weekend?","Voyages-tu ce week-end ?","Choose the correct question.",["You are travelling this weekend?","Are you travelling this weekend?","Do you travelling this weekend?"],1,"Are + subject + verb-ing forms the question."),
 _u5(3,"Will for quick decisions","Use will when you decide at the moment of speaking.","The phone is ringing. I’ll answer it.","Le téléphone sonne. Je vais répondre.","You decide now to help. Say…",["I’ll help you.","I helping you yesterday.","I am help you."],0,"I’ll is a natural quick decision."),
 _u5(4,"Will for predictions","Use will to make a prediction about the future.","I think our team will win.","Je pense que notre équipe va gagner.","Which phrase introduces an opinion prediction?",["I think","Last week","At the moment yesterday"],0,"I think often introduces a prediction."),
 _u5(5,"Going to for intentions","Use be going to for an intention or plan already decided.","I’m going to study after dinner.","Je vais étudier après le dîner.","Choose a planned intention.",["I’m going to learn English.","I learned English tomorrow.","I going learn English."],0,"Be going to expresses an intention."),
 _u5(6,"Going to for visible evidence","Use be going to when present evidence suggests an outcome.","Look at those clouds. It’s going to rain.","Regarde ces nuages. Il va pleuvoir.","Why use going to here?",["There is visible evidence.","It happened last year.","It is a command."],0,"The clouds are evidence for the prediction."),
 _u5(7,"Will versus going to","Will often marks a spontaneous decision; going to often marks a prior plan.","I’ll call now; I’m going to visit her tomorrow.","Je vais appeler maintenant ; je compte lui rendre visite demain.","Which phrase best expresses a prior plan?",["I’m going to visit her.","I’ll answer the phone (decision now).","I answer yesterday."],0,"Going to commonly signals an existing plan."),
 _u5(8,"Future time expressions","Use tomorrow, next week, later, and in two days to locate future events.","We’re leaving next week.","Nous partons la semaine prochaine.","Which phrase means « la semaine prochaine »?",["last week","next week","every week ago"],1,"Next week refers to the coming week."),
 _u5(9,"When clauses for future time","After when, use present simple for a future time clause.","When I arrive, I’ll text you.","Quand j’arriverai, je t’enverrai un message.","Complete: When she ___, we’ll start.",["arrives","will arrive","arrive yesterday"],0,"Present simple follows when in this future time clause."),
 _u5(10,"Before and after in future clauses","Use present simple after before and after when referring to future events.","I’ll eat before I leave.","Je mangerai avant de partir.","Complete: I’ll call you after I ___.",["arrive","will arrive","arriving"],0,"Use present simple after after in this clause."),
 _u5(11,"First conditional: real possibility","Use if + present simple, will + base verb for a possible future result.","If it rains, we’ll stay home.","S’il pleut, nous resterons à la maison.","Choose the correct conditional.",["If it rains, we’ll stay home.","If it will rain, we stay home.","If rain, we stayed home tomorrow."],0,"The if-clause uses present simple."),
 _u5(12,"First conditional negative","Use don’t/doesn’t in the if-clause and won’t in the result when needed.","If he doesn’t hurry, he won’t catch the bus.","S’il ne se dépêche pas, il ne prendra pas le bus.","Complete: If you don’t study, you ___ pass.",["won’t","aren’t","didn’t yesterday"],0,"Won’t expresses the negative future result."),
 _u5(13,"Might for possibility","Use might + base verb when something is possible but uncertain.","We might visit the market later.","Nous irons peut-être au marché plus tard.","Which word shows possibility?",["might","must not","yesterday"],0,"Might means something is possible."),
 _u5(14,"May for possibility","May can express a possibility in a slightly formal style.","The delivery may arrive today.","La livraison arrivera peut-être aujourd’hui.","The delivery ___ arrive today.",["may","does may","may to"],0,"May is followed by the base verb."),
 _u5(15,"Must and have to for obligation","Use must or have to to express a strong obligation.","You have to wear a seat belt.","Tu dois porter une ceinture de sécurité.","Which expresses obligation?",["You have to wear it.","You might wearing it.","You have wearing it."],0,"Have to expresses necessity."),
 _u5(16,"Don’t have to versus mustn’t","Don’t have to means not necessary; mustn’t means prohibited.","You don’t have to come early, but you mustn’t be late.","Tu n’es pas obligé de venir tôt, mais tu ne dois pas être en retard.","Which means « ce n’est pas nécessaire »?",["don’t have to","mustn’t","shouldn’t have"],0,"Don’t have to means no obligation."),
 _u5(17,"Should for recommendations","Use should + base verb to give advice.","You should back up your files.","Tu devrais sauvegarder tes fichiers.","Choose the correct advice.",["You should back up your files.","You should to back up files.","You should backing files."],0,"Should takes the base verb without to."),
 _u5(18,"Could for polite requests","Use could to make a polite request.","Could you speak more slowly, please?","Pourriez-vous parler plus lentement, s’il vous plaît ?","Which is the most polite request?",["Speak slowly!","Could you speak more slowly, please?","You speaking slowly?"],1,"Could you…? is polite and natural."),
 _u5(19,"Would like for offers and wants","Use would like to express a polite want.","I’d like to book a table for two.","Je voudrais réserver une table pour deux.","Complete: I’d like ___ some water.",["to have","having","have yesterday"],0,"Would like is followed by to + verb."),
 _u5(20,"Would you like…?","Use Would you like…? to offer something or invite someone.","Would you like some tea?","Voulez-vous du thé ?","Which sentence makes an offer?",["Would you like some tea?","You like tea yesterday?","Do you would tea?"],0,"Would you like…? makes a polite offer."),
 _u5(21,"Accepting offers politely","Use Yes, please or That would be great to accept an offer.","That would be great, thank you.","Ce serait super, merci.","Choose a polite acceptance.",["That would be great, thank you.","No you give me.","I accept yesterday."],0,"This phrase warmly accepts the offer."),
 _u5(22,"Declining offers politely","Use No, thank you or I’m okay, thanks to decline politely.","No, thank you. I’ve got one already.","Non merci. J’en ai déjà un.","Which response is polite?",["No, thank you.","Give it now.","I no want you."],0,"No, thank you is polite."),
 _u5(23,"Making plans with shall we","Use Shall we + base verb to suggest an activity together.","Shall we study together this evening?","Étudierons-nous ensemble ce soir ?","Complete: Shall we ___ a movie?",["watch","to watch","watching"],0,"Shall we is followed by the base verb."),
 _u5(24,"Suggesting with why don’t we","Use Why don’t we + base verb to make a suggestion.","Why don’t we take the earlier bus?","Pourquoi ne prenons-nous pas le bus plus tôt ?","Which phrase makes a suggestion?",["Why don’t we take the bus?","Why we took bus?","Why don’t taking bus?"],0,"Why don’t we…? introduces a suggestion."),
 _u5(25,"Agreeing to a suggestion","Use Sounds good, Great idea, or That works for me.","Sounds good. Let’s meet at five.","Ça marche. Retrouvons-nous à cinq heures.","Choose a natural agreement.",["Sounds good.","I am agree you.","Sounded good tomorrow."],0,"Sounds good is a natural response."),
 _u5(26,"Disagreeing politely","Give a short reason and suggest another option.","I’m not sure about Friday. Could we meet on Saturday?","Je ne suis pas sûr pour vendredi. Pourrions-nous nous voir samedi ?","Which response offers an alternative politely?",["No. Never.","Could we meet on Saturday instead?","You wrong Friday."],1,"The question proposes an alternative politely."),
 _u5(27,"Invitations with would you like to","Use Would you like to + base verb to invite someone.","Would you like to join us for lunch?","Aimerais-tu te joindre à nous pour le déjeuner ?","Complete: Would you like to ___ us?",["join","joining","joined tomorrow"],0,"Would you like to is followed by to + base verb."),
 _u5(28,"Giving reasons with because","Use because to explain why you accept or refuse a plan.","I can’t come because I’m working late.","Je ne peux pas venir parce que je travaille tard.","Why can’t the speaker come?",["They are working late.","They are at the airport.","They came yesterday."],0,"Because introduces the reason."),
 _u5(29,"Using so to show a result","Use so to connect a reason or situation to its result.","The shop was closed, so we went home.","Le magasin était fermé, alors nous sommes rentrés.","What happened as a result?",["They went home.","They opened the shop.","They bought a ticket."],0,"So introduces the result."),
 _u5(30,"Time expressions: in, on, at","Use at for clock times, on for days, and in for months or years.","The meeting is at ten on Monday in June.","La réunion est à dix heures lundi en juin.","Choose the correct phrase.",["at ten","in ten o’clock","on ten o’clock"],0,"Use at with a clock time."),
 _u5(31,"Appointments and availability","Ask whether someone is free at a particular time.","Are you available on Thursday afternoon?","Es-tu disponible jeudi après-midi ?","Which asks about availability?",["Are you available on Thursday?","You free Thursday yesterday?","Are available you Thursday?"],0,"Are you available…? is natural."),
 _u5(32,"Changing plans","Apologize and explain when you need to change an arrangement.","I’m sorry, but I need to change our plans.","Je suis désolé, mais je dois changer nos plans.","Which phrase signals a change of plans?",["I need to change our plans.","I am plan yesterday.","Plans are changing me."],0,"This phrase clearly explains the change."),
 _u5(33,"Explaining delays","Use I’m running late to say you will arrive later than planned.","I’m running ten minutes late. Please start without me.","J’ai dix minutes de retard. Commencez sans moi, s’il vous plaît.","What does running late mean?",["arriving later than planned","running for exercise","leaving very early"],0,"Running late means behind schedule."),
 _u5(34,"Apologizing for lateness","Say Sorry I’m late and give a brief explanation.","Sorry I’m late; the bus was delayed.","Désolé d’être en retard ; le bus a eu du retard.","Which apology is natural?",["Sorry I’m late.","Sorry I late am.","I apology you late."],0,"Sorry I’m late is natural English."),
 _u5(35,"Confirming arrangements","Repeat the time and place to avoid misunderstanding.","So, we’re meeting outside the library at six, right?","Donc, on se retrouve devant la bibliothèque à six heures, c’est bien ça ?","Why confirm the details?",["To make sure everyone understands the plan","To cancel without saying so","To describe yesterday"],0,"Confirming checks that the details are correct."),
 _u5(36,"Asking for clarification","Use Could you repeat that? or What do you mean?","Could you repeat the time, please?","Pourriez-vous répéter l’heure, s’il vous plaît ?","Which phrase asks someone to repeat information?",["Could you repeat that?","I repeat you.","Repeat yesterday time."],0,"Could you repeat that? is polite."),
 _u5(37,"Checking understanding","Use Do you mean…? to check what someone intended.","Do you mean we should meet at the main entrance?","Veux-tu dire que nous devons nous retrouver à l’entrée principale ?","Which phrase checks meaning?",["Do you mean…?","I mean you yesterday?","What you mean is?"],0,"Do you mean…? checks understanding."),
 _u5(38,"Future plans in a dialogue","Combine going to, arrangements, and time phrases in a short exchange.","I’m going to buy tickets, and we’re leaving at eight.","Je vais acheter les billets et nous partons à huit heures.","What will the speaker do?",["Buy tickets","Cancel the trip","Return a shirt"],0,"The speaker plans to buy tickets."),
 _u5(39,"Weather plans","Use weather expressions to explain a future decision.","If it’s sunny, we’ll have lunch outside.","S’il fait beau, nous déjeunerons dehors.","What happens if it is sunny?",["They will eat outside.","They will take a flight.","They ate yesterday."],0,"The result is having lunch outside."),
 _u5(40,"Study plans","Describe a study intention and a specific arrangement.","I’m going to review vocabulary, and I’m meeting my tutor at four.","Je vais réviser le vocabulaire et je rencontre mon tuteur à quatre heures.","Which phrase describes an arrangement?",["I’m meeting my tutor at four.","I reviewed last year.","I review yesterday."],0,"Present continuous can describe a fixed arrangement."),
 _u5(41,"Work plans","Explain future work tasks using going to and time expressions.","We’re going to finish the report by Friday.","Nous allons terminer le rapport d’ici vendredi.","What is the deadline?",["Friday","last Friday only","next year"],0,"By Friday gives the deadline."),
 _u5(42,"Travel contingency plans","Use if + present simple to discuss what you will do in a possible situation.","If we miss the train, we’ll take the next one.","Si nous ratons le train, nous prendrons le suivant.","What will they do if they miss it?",["Take the next train","Walk to the airport","Cancel every plan"],0,"The result clause says they will take the next train."),
 _u5(43,"A short telephone plan","Open a call, state the plan, and confirm the time.","Hi, are we still meeting at seven? Yes, see you there.","Salut, on se voit toujours à sept heures ? Oui, à tout à l’heure.","What does still meeting mean?",["The plan remains unchanged","The meeting happened last week","The plan is unknown forever"],0,"Still meeting checks that the arrangement remains."),
 _u5(44,"A message about changed plans","Write a short message that apologizes and proposes a new time.","Sorry, I can’t make six. Could we meet at seven instead?","Désolé, je ne peux pas à six heures. Pourrions-nous plutôt nous voir à sept heures ?","What time is proposed instead?",["Seven","Six only","Tomorrow morning for certain"],0,"The speaker proposes seven instead."),
 _u5(45,"Integrated future review","Choose future forms based on intention, quick decision, arrangement, or possibility.","I’ve booked the tickets. We’re leaving at eight, and it might rain.","J’ai réservé les billets. Nous partons à huit heures et il pourrait pleuvoir.","Which phrase expresses uncertainty?",["might rain","have booked","are leaving"],0,"Might expresses possibility, not certainty."),
 _u5(46,"Unit conversation preparation","Prepare to discuss plans, invitations, schedules, and alternatives.","Would you like to visit the museum on Saturday? We could meet at ten.","Aimerais-tu visiter le musée samedi ? Nous pourrions nous retrouver à dix heures.","Which answer politely accepts?",["Yes, that sounds great.","I accept you yesterday.","No, you must go."],0,"That sounds great is a natural acceptance."),
 _u5(47,"Future arrangements with friends","Use present continuous for a fixed arrangement and mention the time.","I’m having lunch with my classmates at one.","Je déjeune avec mes camarades à treize heures.","Which phrase gives a fixed arrangement?",["I’m having lunch at one.","I have lunch yesterday.","I having lunch one."],0,"I’m having lunch is present continuous for a planned arrangement."),
 _u5(48,"Making a backup plan","Use in case to prepare for a possible problem.","Take an umbrella in case it rains.","Prends un parapluie au cas où il pleuvrait.","Why take an umbrella?",["To be prepared for possible rain.","Because it rained last month.","To cancel the trip."],0,"In case introduces a possible situation you prepare for."),
 _u5(49,"Talking about hopes","Use hope + present simple or hope to + verb for a desired future.","I hope we have enough time to visit the museum.","J’espère que nous aurons assez de temps pour visiter le musée.","Which phrase expresses a hope?",["I hope we have enough time.","I hope we had time yesterday tomorrow.","I hope to enough time."],0,"I hope expresses a desired outcome."),
 _u5(50,"Unit 5 mixed practice","Choose the form that matches an arrangement, intention, or quick decision.","I’ve planned the trip, so I’m going to book the hotel today.","J’ai planifié le voyage, donc je vais réserver l’hôtel aujourd’hui.","Which form expresses the intention?",["am going to book","booked yesterday","am book"],0,"Going to book expresses the speaker’s intention."),
